import xml.etree.ElementTree as ET

tree = ET.parse('/tmp/page1_bbox.html')
root = tree.getroot()
ns = {'x': 'http://www.w3.org/1999/xhtml'}

# Find all words on page 1
for page in root.findall('.//x:page', ns):
    pw = page.get('width')
    ph = page.get('height')
    print(f"Page size: {pw} x {ph}")
    for line in page.findall('.//x:line', ns):
        for word in line.findall('x:word', ns):
            t = word.text
            if t and t.strip() in ['001','002','003','040','041','042','043','044','045']:
                print(f'  "{t.strip()}" xMin={word.get("xMin")} yMin={word.get("yMin")} xMax={word.get("xMax")} yMax={word.get("yMax")}')
